def step(state, action):
    dr, dc = _action_vector(action)
    ar, ac = state["anchor"]
    new_state = {
        "h": state["h"],
        "w": state["w"],
        "anchor": [ar + dr, ac + dc],
        "cells": state["cells"],
    }
    events = []
    return new_state, events

def render(state):
    h, w = state["h"], state["w"]
    grid = [[UNKNOWN for _ in range(w)] for _ in range(h)]

ar, ac = state["anchor"]
    for dr, dc, color in state["cells"]:
        r, c = ar + dr, ac + dc
        if 0 <= r < h and 0 <= c < w:
            grid[r][c] = color
    return grid

